INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0f1d6c9bd1b9ff16f38ede170b876175e94606eb/content/books/zizhi-tongjian/vol-287/year-0947/part-08/sources/library/jiuwudaishi-100-december-return/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002442；EPUB电子本，纸本及异文待核", "id": "a917de71-8136-5655-b1cf-8dc7b4b83d92"}, {"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0f1d6c9bd1b9ff16f38ede170b876175e94606eb/content/books/zizhi-tongjian/vol-287/year-0947/part-08/sources/library/jiuwudaishi-100-november-surrender/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002441；EPUB电子本，纸本及异文待核", "id": "c8994539-6e6b-53d9-a129-1611626127c2"}, {"title": "旧五代史·卷一百〇九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0f1d6c9bd1b9ff16f38ede170b876175e94606eb/content/books/zizhi-tongjian/vol-287/year-0947/part-08/sources/library/jiuwudaishi-109-du-surrender/source.txt", "note": "《旧五代史》卷一百〇九，段落 jiu-wudaishi-205deb4a7860-p002618；EPUB电子本，纸本及异文待核", "id": "a595b80d-974b-5b70-ad1b-894fcf093070"}, {"title": "旧五代史·卷109·杜重威传·家世与恒州任职", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/364ae8263b649ce7f7349c1b24424be505327bcc/content/books/zizhi-tongjian/vol-284/year-0945/part-04/sources/library/jiuwudaishi-109-du-wife/source.txt", "note": "《旧五代史》卷109·杜重威传·家世与恒州任职，段落 jiu-wudaishi-205deb4a7860-p002616；已核卷号、传主及连续原文，电子本与异文待纸本校核。", "id": "f9349e26-5e2f-5c7c-842e-180f08f4a08e"}, {"title": "宋史·巻二百五十四", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0f1d6c9bd1b9ff16f38ede170b876175e94606eb/content/books/zizhi-tongjian/vol-287/year-0947/part-08/sources/library/songshi-254-hou-yi-shu/source.txt", "note": "《宋史》巻二百五十四，段落 songshi-9c6e46fee832-p057446；EPUB电子本，纸本及异文待核", "id": "6703918e-e296-5f0e-92db-166a7fad4c21"}, {"title": "宋史·巻四百七十九", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/0f1d6c9bd1b9ff16f38ede170b876175e94606eb/content/books/zizhi-tongjian/vol-287/year-0947/part-08/sources/library/songshi-479-han-baozhen-campaign/source.txt", "note": "《宋史》巻四百七十九，段落 songshi-9c6e46fee832-p074975；EPUB电子本，纸本及异文待核", "id": "6ab0575d-0349-5fb6-80e7-493693aac166"}, {"title": "资治通鉴·后汉纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/22f4519de0a37af02e4e5c96623c1efb65f06888/content/books/zizhi-tongjian/vol-287/year-0947/part-07/sources/library/tongjian-287-947-september-siege/source.txt", "note": "《资治通鉴》后汉纪二，段落 zizhi-tongjian-a63549944a71-p003410；电子底本待考，分段待核", "id": "5d8b8507-63f3-5c8e-b85b-503feb404d59"}, {"title": "旧五代史·卷一百", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/22f4519de0a37af02e4e5c96623c1efb65f06888/content/books/zizhi-tongjian/vol-287/year-0947/part-07/sources/library/jiuwudaishi-100-october-siege/source.txt", "note": "《旧五代史》卷一百，段落 jiu-wudaishi-205deb4a7860-p002440；EPUB电子本，纸本及异文待核", "id": "c2b8b8f7-a863-57b6-a5e8-74b3d595e9ec"}, {"title": "新五代史·卷六十七", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/727493791cbf73933108431c692275b3b8c9af2b/content/books/zizhi-tongjian/vol-287/year-0947/part-03/sources/library/xinwudaishi-067-qian-zong-succession/source.txt", "note": "《新五代史》卷六十七，段落 xin-wudaishi-b08f244b9241-p003375；EPUB电子本，纸本及异文待核", "id": "6bc7a35e-fa90-5b15-8ce4-7a044f9b0446"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "陈观", "aliases": ["陳觀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉给事中。947年十月刘知远亲征邺都时，派他入城向杜重威宣谕归降，杜重威闭门拒绝。生卒年未载。", "biography": null, "status": "draft", "id": "91fa9e7e-dc34-57a5-9199-5fe3f6f5ed8f"}, {"name": "慕容彦超", "aliases": ["慕容彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋濮州刺史，原属吐谷浑，与刘知远同母。945年正月随皇甫遇侦察契丹军，在榆林店受围，与皇甫遇共同救回杜知敏，得到安审琦援军后返回相州。出生及死亡年本段未载。", "biography": null, "status": "draft", "id": "e0c11a24-a441-5d69-b8e3-b5bdc109357b"}, {"name": "张琏（幽州军指挥使）", "aliases": ["張璉（幽州軍指揮使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年率领赵延寿留在恒州的幽州亲兵，杜重威请求借其军守魏州。是否与895年所见同名人物有关，未得确证，分别建档。生卒年未载。", "biography": null, "status": "draft", "id": "8b130b3f-0eba-556e-9baa-b43bd73ead49"}, {"name": "韩训", "aliases": ["韓訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉内殿直。947年十一月向刘知远献攻城器具，刘知远回应城池依赖众人之心，认为器具不是关键。生卒年未载。", "biography": null, "status": "draft", "id": "2dd516ed-4907-5fd4-9b84-1063e11c32b8"}, {"name": "王敏（杜重威判官）", "aliases": ["王敏（金乡）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金乡人，杜重威的观察判官。947年杜重威叛乱时屡次哭谏，未获听从；邺都粮尽后奉杜重威表出城请降。《旧五代史》职名作节度判官。生卒年未载。", "biography": null, "status": "draft", "id": "8f7fed9a-5ef2-5c02-8b61-b0b1733a81ba"}, {"name": "杜弘琏", "aliases": ["杜弘璉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杜重威之子。947年十一月乙亥出邺都见刘知远，参与父亲出降前的接洽。对应接洽在《旧五代史》杜重威传中写作宏遂，姓名差异保留；不与已录质子杜弘璲直接合并。生卒年尚未录入。", "biography": null, "status": "draft", "id": "dd9e1585-5674-5445-82b7-f38922a7afea"}, {"name": "乐平长公主（杜重威妻）", "aliases": ["乐平长公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的妹妹、杜重威的妻子。937年的记载称她为乐平长公主。", "biography": null, "status": "draft", "id": "7cf58667-5bd6-58c5-8ebe-c3c1d463a473"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "王章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州南乐人，曾任孔目官，随刘知远到太原。947年任权三司使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "154bd412-f052-5459-9c17-951cfcd91759"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "刘信", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：刘信。", "biography": null, "status": "draft", "id": "e00e40ed-f971-5df9-b8a9-4dc1cc38f275"}, {"name": "钱弘倧", "aliases": ["錢弘倧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲鹿氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "141c421e-2a7d-5b59-91f9-bf5ec3f726df"}, {"name": "胡进思", "aliases": ["胡進思"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "湖州人，吴越右统军使。943年条下记章德安与李文庆被贬后，史书称他与阚璠更加专横。生卒年尚未核。", "biography": null, "status": "draft", "id": "4f56160f-2b15-5a0c-9fa8-9523947bb1df"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "吴崇恽", "aliases": ["吳崇惲"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀将领。947年以雄武都押牙身份带王处回书信招侯益归蜀。《宋史》侯益传记他为侯益旧属、秦州押衙，后任绵州刺史，受孟昶派遣厚赠侯益；职名按出处分别保留。生卒年未载。", "biography": null, "status": "draft", "id": "101778ed-1ba3-58c1-b7d5-0a116caec712"}, {"name": "王处回", "aliases": ["王處回"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王处回，为税官请免的中门副使。", "biography": null, "status": "draft", "id": "159fd2b3-759b-522a-a971-11356c6fe970"}, {"name": "侯益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：侯益，平遥前直指挥使、脱身返洛者。", "biography": null, "status": "draft", "id": "d164db58-b751-53af-9dac-d5112662da44"}, {"name": "张虔钊", "aliases": ["張虔釗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张虔钊。", "biography": null, "status": "draft", "id": "b4b03cda-5958-57ef-b1ca-a5c8e1fb4985"}, {"name": "何重建", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋曹州防御使，云州、朔州一带胡人。942年受命援救延州，二月被任命为彰武留后。生卒年未载。", "biography": null, "status": "draft", "id": "32fa2f01-0372-5b5b-83b5-c66e445ba1c1"}, {"name": "韩保贞", "aliases": ["韓保貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：韩保贞，丰德库使、曾事藩邸者。", "biography": null, "status": "draft", "id": "7090cd80-1efa-59ab-9b8f-05f88da57d52"}, {"name": "李廷珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀将领。947年十二月任奉銮肃卫都虞候，率二万兵出子午谷援长安。生卒年尚未录入。", "biography": null, "status": "draft", "id": "376820ae-41ca-57e0-b117-00976a8545fc"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "杜重威曾称刘知远到来就投降，却闭门拒绝陈观宣谕", "start_year": 947, "end_year": 947, "time_original": "947年十月，具体日未载", "dynasty": "五代十国", "description": "杜重威曾称刘知远到来就投降，却闭门拒绝陈观宣谕。", "phases": [], "location_name": "邺都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "00b2552c-d0a8-5563-a0c3-fbc1f588bb35"}, {"title": "邺都粮食渐尽，许多将士出城归降", "start_year": 947, "end_year": 947, "time_original": "947年十月，具体日未载", "dynasty": "五代十国", "description": "邺都粮食渐尽，许多将士出城归降。", "phases": [], "location_name": "邺都", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5be2431f-4e35-5c0d-b53c-8dac987921c6"}, {"title": "慕容彦超坚持攻城，刘知远同意", "start_year": 947, "end_year": 947, "time_original": "947年十月丙午攻城之前，具体请求日未载", "dynasty": "五代十国", "description": "慕容彦超坚持攻城，刘知远同意。", "phases": [], "location_name": "邺都军营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "83a030e4-ec70-5dcd-858b-d3c3ee955cf8"}, {"title": "刘知远督军攻邺都失败，伤者万余、死者千余", "start_year": 947, "end_year": 947, "time_original": "947年十月丙午，自寅至辰", "dynasty": "五代十国", "description": "刘知远督军攻邺都失败，伤者万余、死者千余。", "phases": [], "location_name": "邺都城下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c21cc8be-fd5c-535f-96ed-0fc030f77c42"}, {"title": "契丹曾留一千五百名幽州兵驻守大梁", "start_year": 947, "end_year": 947, "time_original": "947年契丹占据大梁期间，具体驻留日未